  "czatAi.dolaczoneZdjeciaMakietkaWgrala": "\n\n[Attached photos – Makietka uploaded them to the project (obrazy_projektu); place them with the wstaw_obraz tool:\n{join}]",
  "czatAi.jakOdpowiadac": "HOW TO REPLY: you have no direct access to Makietka – the user carries the messages. Write briefly (in the user's language) what you will do, then ONE code block with commands:\n```makietka\n[{\"narzedzie\": \"tool_name\", \"parametry\": { … }}]\n```\nThe user will paste it into Makietka; it will run the commands in order and give you the results. When you first need to read something (czytaj, opis_formatu…), send only those commands and wait for the results. Give parameters exactly as in the list (* – required).\n\nTOOLS:\n{narzedzia}\n\nPROJECT STATE (przeglad_projektu):\n{przeglad}\n\nUSER'S TASK:\n{tekst}",
