  "sekcjaSpecjalna.zwijaneLamanaCRolowana": "Roll fold (C-fold)",
  "sekcjaWzorcePole.wzorceNaStronachTej": "Master pages on this section's pages",
  "sekcje.bezGrzbietu": "No spine",
  "sekcje.bezGrzbietuWZdaniu": "no spine",
  "sekcje.cofnij": "Undo",
  "sekcje.dodajSekcje": "Add section",
  "sekcje.dodanoPusteStrony": "Added {brakuje} {brakuje|blank page|blank pages} – section “{nazwa}” has {doPelnej} pages.",
  "sekcje.dodanoSekcjaMaStron": "Added {brakuje} {ile} – section “{nazwa}” has {doPelnej} pages.",
  "sekcje.grafikaOkladkiSieNie": "{opis} The cover artwork isn't printed – only elements with foiling or embossing remain on the cover material (Print colors → Finishing). The 3D mockup shows the cover material in the chosen color.",
  "sekcje.grzbietMm": "Spine (mm)",
  "sekcje.grzbietMm2": "Spine {liczba} mm",
  "sekcje.grzbietMmPusteLiczony": "Spine (mm, empty – calculated)",
  "sekcje.grzbietMmWZdaniu": "spine {liczba} mm",
  "sekcje.innyRozmiar": "{nazwa} (different size)",
  "sekcje.kalendarzPola": "The first page of the section repeats for each data row. Put fields on it: {data}, {dzien}, {miesiac}, {dzien_tygodnia}, {tydzien}, {swieto}; “wolne” has the value “tak” on Sundays and holidays (e.g. for a colour that depends on data).",
  "sekcje.lewy": "Left",
  "sekcje.nadrukNaKartonieZabezpieczony": "Printed on board, protected with laminate. You set foiling, UV varnish and embossing on elements (Print colors → Finishing).",
  "sekcje.nowaSekcja": "New section",
  "sekcje.okladkaMm": "{x} · Cover {liczba} × {liczba2} mm",
  "sekcje.podloze.folia": "Pages on a checkerboard – the film is transparent. Inks on film show through; under elements that should be opaque, set a white underprint (Print colours → Finishing → White underprint).",
  "sekcje.podloze.kolor": "The paper colour shows on the pages but isn’t printed. White isn’t an ink: white elements come out in the paper colour – unless they get a white underprint (Print colours → Finishing).",
  "sekcje.prawy": "Right",
  "sekcje.przyGrzbiecie": "At the spine",
  "sekcje.razemZNiaZostanie": "{stronyIle} pages will be deleted along with it.",
  "sekcje.sekcjaBedziePilnowacLiczby": "The section will keep the page count a multiple of {skladka}.",
  "sekcje.sekcjaJestPusta": "The section is empty.",
  "sekcje.specjalna.arkusz": "You design one item (or more from data – a series). In the PDF the items are placed side by side on the sheet, with crop marks; a sticker gets a die-cut line.",
  "sekcje.specjalna.obwoluta": "The dimensions come from the project’s hard cover (boards and spine) – when pages are added, the jacket recalculates itself. Flap 0 – about half the width of the front.",
  "sekcje.specjalna.skladanka": "Each page of this section is one sheet with model parts. Material thickness is calculated from the paper weight – slots are wider by it, and inner tabs and flaps shorter. When printing at home, cut and fold lines are printed; for a print shop they go into the PDF as separate colours (“CutContour”, “Crease”, “Glue”).",
  "sekcje.specjalna.trojdzielny": "The header folds back on the crease; the calendar pads and the advertising strip are separated by perforation. The calendar fields are places for glued-on date pads.",
  "sekcje.specjalna.ulotka": "The section has two sides: outer (cover, back) and inner. In a roll fold, the panel folded inside is narrower – otherwise it buckles at the fold. Text shouldn’t sit on a fold.",
  "sekcje.specjalna.wyklejka": "The format comes from the book block: two of its leaves side by side, folded in the middle. The “On the cover” half is glued to the inside of the hard cover, the other is a loose leaf – its thickness adds to the spine. Endpapers have no page numbers; in the PDF they are a separate spread section, with bleed.",
  "sekcje.specjalna.wykrojnik": "The cut and fold lines go into the PDF in separate colours (“CutContour” and “Crease”) – the printer doesn’t print them, only cuts and creases. Anything outside the cut line will be cut off.",
  "sekcje.srodekOpis": "Inside: {stron} pages ({kartek} leaves × {kartka} mm), page {sz} × {wy} mm.",
  "sekcje.toJedyneStronyW": "These are the only pages in the project – move some page to another section first.",
  "sekcje.tylIPrzod": " The back and front share the rest of the width equally around the spine.",
  "sekcje.ustawieniaSekcji": "Section settings",
  "sekcje.usunSekcje": "Delete section",
  "sekcje.usunacSekcje": "Delete section “{nazwa}”?",
  "sekcje.usunietoSekcje": "Deleted section “{nazwa}”.",
