  "skladankaSzablony.ruchMmUchwytWystaje": "Travel {r2} mm; the handle sticks out beyond the card.",
  "skladankaSzablony.scianyIDachJako": "Walls and roof as one solid, unfolded automatically – gables, roof slopes and walls with tabs and numbers.",
