  "tresc.makietaD.kontekstGrafikiZostalUtracony": "the graphics context was lost",
  "tresc.makietaOkno.alboOtworzMakietkeWB": "Or open Makietka in <b>Safari</b> – on older Macs it usually shows the mockup without changing any settings.",
  "tresc.makietaOkno.nieznanyBladGrafiki": "unknown graphics error",
  "tresc.makietaOkno.poprzednioMakietaZamknelaSieNieoczekiwanie": "Last time the mockup closed unexpectedly (usually the phone runs out of memory) – now it works in saving mode: fewer pages at once and lower page resolution.",
  "tresc.makietaOkno.sprawdzWChromeUstawienieB": "Check the Chrome setting <b>Settings → System → Use graphics acceleration when available</b> – it should be on (then restart Chrome).",
  "tresc.makietaOkno.toUrzadzenieNiePokazujeGrafiki": "This device doesn’t show 3D graphics – the mockup is drawn in a simplified version (without cast shadows and gloss). Rotating and page turning work the same.",
  "tresc.makietaOkno.wpiszWPaskuAdresuB": "Type <b>chrome://gpu</b> in the address bar. If “WebGL” shows “Unavailable” or “Software only”, Chrome has blocked this computer’s graphics card (common on older computers). Then open <b>chrome://flags/#ignore-gpu-blocklist</b>, set “Override software rendering list” to <b>Enabled</b> and restart Chrome.",
  "tresc.makietaOkno.zaktualizujPrzegladarkeISystemPrzy": "Update the browser and the system; in battery-saving mode graphics may be turned off – turn it off for a moment.",
  "tresc.makietaOpis.broszuraZeszytowaArkuszeZlozoneNa": "Saddle-stitched booklet – sheets folded in half and stapled at the fold (page count divisible by 4).",
  "tresc.makietaOpis.kalendarzSciennyMaZwykle13": "A wall calendar usually has 13 leaves (cover and 12 months) – the project doesn’t have them. Missing leaves will be white; start from the “Wall calendar with backing” template.",
  "tresc.makietaOpis.miekka": "soft",
  "tresc.makietaOpis.miekkaKlejona": "soft glued",
  "tresc.makietaOpis.notesNaSpiraliStronyProjektu": "Spiral notebook – a spiral binds the project pages; the cover (if any) will be the first leaf.",
  "tresc.makietaOpis.projektNieMaOkladkiMakieta": "The project has no cover – the mockup will show an empty, dark binding. Add a section of the “Cover” type with a hard binding or start from the “Hardcover book” project template.",
  "tresc.makietaOpis.twarda": "hard",
