  "tresc.oknoDruku.broszuraDrukujBDwustronnieObracanie": "Booklet: print <b>double-sided, flip on the short edge</b> (the sheet lies landscape). On the back of sheet 1 are pages 2 and 7.",
  "tresc.oknoDruku.drukarkaBezDrukuDwustronnegoWydrukuj": "Printer without double-sided printing: first print <b>only the odd pages</b>, put the stack back (printed side as the printer’s instructions say), then the <b>even</b> ones.",
  "tresc.oknoDruku.dwustronnieKartkaZKilkomaStronami": "Double-sided: a sheet with several pages lies landscape – flip on the <b>short</b> edge.",
  "tresc.oknoDruku.dwustronnieObracaniePoBDluzszej": "Double-sided: flip on the <b>long</b> edge (sheet portrait).",
  "tresc.oknoDruku.jesliWybralesZnakiCieciaPo": "If you chose crop marks, trim the edges along the marks after stapling (with a knife and ruler or at a copy shop).",
  "tresc.oknoDruku.najpierwWydrukujBJednaKartke": "First print <b>one test sheet</b> (in the printer dialog: pages 1–2) and check that the pages are placed correctly.",
  "tresc.oknoDruku.wRzeczywistymRozmiarzeZmniejszoneTylko": "at actual size (reduced only when they don’t fit)",
  "tresc.oknoDruku.zlozKartkiRazemNaPol": "Fold the sheets together in half (first sheet on top), align them and <b>staple at the fold</b> (2 staples). Split a thick booklet into signatures of a few sheets.",
  "tresc.oknoPdf.obrazyStronSaPrzeliczoneNa": "Page images are converted to CMYK with this profile. Black and grey text, shapes and shadows use black ink only (also on a photo) and are saved losslessly, so the letters are sharp; the photos themselves use four inks, as the profile says, as JPEG. The file is larger than regular page images.",
  "tresc.oknoPdf.zdjeciaSaPrzeliczoneNaCmyk": "Photos are converted to CMYK with this profile, at the resolution from the “Quality” field (JPEG photos stay JPEG in four inks, other images lossless) – the file will be larger.",
  "tresc.oknoPdf.zdjeciaZostajaWRgbZ": "Photos stay in RGB with an sRGB description – the printer converts them to inks using the attached profile (this conforms to PDF/X-4).",
  "tresc.panelStrony.bezWzorcow": "no masters",
