  "tresc.skladanka.odpadWyciecie": "Waste (cut-out)",
  "tresc.skladanka.sciana": "Face",
  "tresc.skladanka.zegnijWszystkieLiniePrzedKlejeniem": "Score all lines before gluing – place a ruler and draw the blunt side of a knife along it. Dash–dot (“mountain”) – fold away from you, the print stays outside; dashes only (“valley”) – towards you. Fold the tabs underneath.",
  "tresc.skladankaNarzedzia.bryla": "Solid",
  "tresc.skladankaNarzedzia.liniaKlejeniaKliknijPoczatekI": "Glue line: click the start and end anywhere in the part – it doesn’t have to reach the edge (Esc finishes). Draw a curve or polyline with the line or pen on the part, select it and use [Glue line].",
  "tresc.skladankaNarzedzia.liniaKlejeniaWDowolnymMiejscu": "Glue line – anywhere on a face",
  "tresc.skladankaNarzedzia.miejsceKlejeniaKliknijWCzesci": "Glue area: click in the part (with Shift – on the underside, unprinted). Esc finishes.",
  "tresc.skladankaNarzedzia.naciecieKliknijPoczatekIKoniec": "Cut: click the start and end – inside the part or from its edge, at any angle (Esc finishes). Curves or polylines: draw a line or pen on the part, select it and use [Cut].",
  "tresc.skladankaNarzedzia.naciecieLiniaCieciaWSrodku": "Cut – a cut line inside the part, at any angle",
  "tresc.skladankaNarzedzia.polaczKliknijPrzyKrawedziKtora": "Join: click near the edge that gets the tab, then near the edge it sticks to – or inside a face (glue area). Esc finishes.",
  "tresc.skladankaNarzedzia.polaczKrawedzZKrawedziaAlbo": "Join – edge to edge or to a place",
  "tresc.skladankaNarzedzia.rozetnijKliknijPunktNaKrawedzi": "Split: click a point on a part’s edge, then a second one – the part splits in two with a tab on the cut line (Esc finishes).",
  "tresc.skladankaNarzedzia.scalKliknijPrzyKrawedziZ": "Merge: click near an edge with a pair number – the other part joins at that place and the edge becomes a fold (Esc finishes).",
  "tresc.skladankaNarzedzia.szczelinaKliknijPoczatekIKoniec": "Slot: click the start and end of the cut in the part – the width comes from the material thickness (Esc finishes).",
  "tresc.skladankaNarzedzia.szczelinaNaWypustkeZSzerokoscia": "Slot – for a tab (with width)",
  "tresc.skladankaNarzedzia.wPlikuNieMaScian": "The file has no faces – is it really an OBJ or STL model?",
  "tresc.skladankaNarzedzia.wyjmijZCzesciDoEdycji": "Take out of the part (to edit)",
  "tresc.skladankaNarzedzia.zeSkosnaLiniaPoDrugiej": " – with a slanted line on the other side of the spine the attached part stands at an angle like a V-fold",
  "tresc.skladankaNarzedzia.zgiecieDwaKliknieciaNaKrawedziach": "Fold – two clicks on edges",
  "tresc.skladankaNarzedzia.zgiecieKliknijPunktNaKrawedzi": "Fold: click a point on a part’s edge, then a second point on an edge – the line splits the part into faces (Esc finishes).",
